import Foundation

@main
struct EngineChecks {
    static func main() {
        func check(_ condition: @autoclosure () -> Bool, _ name: String) {
            guard condition() else { fatalError("FAILED: \(name)") }
            print("PASS: \(name)")
        }
        let changed = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.changed), allowRestingHR: true, allowHRV: true)
        check(changed.restingHR.baseline?.median == 60, "RHR median independent of current 67")
        check(changed.hrv.baseline?.median == 52, "HRV has its own 52 ms baseline")
        check(changed.restingHR.delta == 7 && changed.hrv.delta == -10, "Opposite directions use separate units")
        check(changed.restingHR.baseline?.validDays == 14, "Today is excluded from historical sample count")
        check(changed.restingHR.isOutsideUsualRange && changed.hrv.isOutsideUsualRange, "Changes outside calculated teaching bands")
        check(changed.explanation.contains("42 ms") && changed.explanation.contains("52 ms"), "Explanation grounded in HRV evidence")
        let stable = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.steady), allowRestingHR: true, allowHRV: true)
        check(!stable.restingHR.isOutsideUsualRange && !stable.hrv.isOutsideUsualRange, "Stable day stays within both bands")
        let partial = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.missingHRV), allowRestingHR: true, allowHRV: true)
        check(partial.canExplain && !partial.usesHRV && partial.hrv.current == nil, "Missing HRV does not block RHR or fabricate value")
        check(!partial.explanation.contains("42 ms"), "Missing HRV never appears in explanation")
        let disabled = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.changed), allowRestingHR: true, allowHRV: false)
        check(disabled.hrv.current == nil && disabled.hrv.baseline == nil && disabled.hrv.history.isEmpty, "Opted-out HRV is omitted completely")
        check(!disabled.explanation.contains("42 ms"), "Opted-out HRV is not explained")
        let denied = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.changed), allowRestingHR: false, allowHRV: true)
        check(!denied.canExplain && !denied.usesHRV, "HRV cannot bypass unavailable primary metric")
        let short = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.shortHistory), allowRestingHR: true, allowHRV: true)
        check(short.restingHR.availability == .insufficientHistory(validDays: 9, requiredDays: 14), "Short history explicitly reports 9/14")
        check(!short.canExplain && short.restingHR.delta == nil, "Insufficient history does not produce a delta")
        let empty = DailyCheckEngine.report(readings: [], allowRestingHR: true, allowHRV: true)
        check(!empty.canExplain && empty.restingHR.availability == .noCurrentSample, "Empty input has no inference about authorization")
        let noAI = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.noAI), allowRestingHR: true, allowHRV: true)
        check(noAI.explanation == changed.explanation, "Deterministic explanation works without AI")
        var gap = DailyCheckEngine.demo(.changed)
        let first = gap.removeFirst()
        gap.insert(DailyReading(day: first.day - 1, date: first.date.addingTimeInterval(-86400), restingHR: 999, hrvSDNN: 999), at: 0)
        let gapped = DailyCheckEngine.evidence(metric: .restingHR, readings: gap, enabled: true)
        check(gapped.availability == .insufficientHistory(validDays: 13, requiredDays: 14), "Out-of-window record cannot fill missing calendar day")
        let invalid = [DailyReading(day: 0, date: Date(), restingHR: .nan, hrvSDNN: -1)]
        check(DailyCheckEngine.evidence(metric: .restingHR, readings: invalid, enabled: true).current == nil, "Non-finite current value rejected")
        check(DailyCheckEngine.median([1, 9, 2, 4]) == 3, "Median averages middle pair")
        var duplicates = DailyCheckEngine.demo(.changed)
        duplicates.append(duplicates.last!)
        let duplicated = DailyCheckEngine.evidence(metric: .restingHR, readings: duplicates, enabled: true)
        check(duplicated.availability == .noCurrentSample, "Duplicate latest day cannot silently replace today with yesterday")
        let shuffled = DailyCheckEngine.report(readings: DailyCheckEngine.demo(.changed).reversed(), allowRestingHR: true, allowHRV: true)
        check(shuffled.explanation == changed.explanation, "Input order does not change daily evidence")
        guard CommandLine.arguments.count > 1 else { fatalError("Missing workshop JSON test resource") }
        let dataset = try! WorkshopDataset.load(from: URL(fileURLWithPath: CommandLine.arguments[1]))
        check(dataset.profiles.count == 2, "Two named simulated profiles loaded")
        for profile in DemoProfile.allCases {
            let records = dataset.replay(profile: profile, through: 60)
            check(records.count == 60, "\(profile.displayName): 60 original workshop days")
            let replay = dataset.replay(profile: profile, through: profile.defaultReplayDay)
            check(replay.last?.day == profile.defaultReplayDay, "\(profile.displayName): replay has no future samples")
            let result = DailyCheckEngine.report(readings: replay, allowRestingHR: true, allowHRV: true)
            check(result.canExplain && result.usesHRV, "\(profile.displayName): both metrics have valid own baselines")
            let early = DailyCheckEngine.report(readings: dataset.replay(profile: profile, through: 10), allowRestingHR: true, allowHRV: true)
            check(early.restingHR.availability == .insufficientHistory(validDays: 9, requiredDays: 14), "\(profile.displayName): early replay reaches fallback")
            print("WORKSHOP \(profile.displayName): RHR \(result.restingHR.current!) / \(result.restingHR.baseline!.median), SDNN \(result.hrv.current!) / \(result.hrv.baseline!.median)")
        }
        let aiInput = AIExplanationInput(report: changed, source: "Synthetic fixture", exerciseContext: false)
        check(aiInput.facts.contains("current 67 bpm") && aiInput.facts.contains("current 42 ms"), "AI input uses computed evidence only")
        check(aiInput.accepts("The resting heart rate is above its own baseline, while HRV is below its own baseline."), "Qualitative AI recap passes basic format screen")
        check(!aiInput.accepts("Your current heart rate is 999 bpm and your HRV is 400 ms."), "AI cannot add numeric claims")
        check(!aiInput.accepts("You have an infection and should take medication."), "Clinical advice output uses fallback")
        let disabledAIInput = AIExplanationInput(report: disabled, source: "Synthetic fixture", exerciseContext: false)
        check(!disabledAIInput.facts.contains("42 ms") && !disabledAIInput.facts.contains("52 ms"), "Opted-out HRV values never enter model input")
        check(!disabledAIInput.accepts("Your HRV is lower than your personal baseline."), "AI cannot reintroduce opted-out HRV")
        check(!AIExplanationInput(report: short, source: "Synthetic fixture", exerciseContext: false).accepts("Your resting heart rate is above usual."), "Insufficient evidence cannot produce AI recap")
        check(!aiInput.accepts(""), "Empty model response uses fallback")
        let chatEvidence = PHIChatEvidence(input: aiInput)
        check(chatEvidence.metrics.contains("67 bpm") && chatEvidence.metrics.contains("42 ms"), "Chat metrics use engine values")
        check(chatEvidence.recovery.contains(changed.explanation), "Recovery tool uses the same engine comparison")
        let disabledChat = PHIChatEvidence(input: disabledAIInput)
        check(!disabledChat.metrics.contains("HRV") && !disabledChat.recovery.contains("42 ms"), "Chat tools withhold opted-out HRV")
        let deniedChat = PHIChatEvidence(input: .init(report: denied, source: "Synthetic fixture", exerciseContext: false))
        check(!deniedChat.metrics.contains("67 bpm") && !deniedChat.metrics.contains("42 ms"), "Chat metrics respect primary access")
        check(deniedChat.recovery.contains("access is disabled"), "Recovery explains the primary access fallback")
        let shortChat = PHIChatEvidence(input: .init(report: short, source: "Synthetic fixture", exerciseContext: false))
        check(shortChat.metrics.contains("baseline comparison is unavailable") && shortChat.recovery.contains("insufficient"), "Chat does not calculate baselines from short history")
        let topic = PHIChatTopic.matching("What does the recovery comparison show?")
        check(PHIChatTopic.followUp("What does that mean?", previous: topic)?.answer(using: chatEvidence) == chatEvidence.recovery, "Swift chat follow-ups reuse the preceding topic")
        check(PHIChatTopic.followUp("Unrelated question", previous: topic) == nil, "Unrelated prompts do not reuse the preceding topic")
        var budget = PHISimulatedBudget()
        budget.record("12345")
        budget.record("👋")
        check(budget.used == 3 && PHISimulatedBudget().used == 0, "Simulated budget counts UTF-8 bytes and resets per chat")
        let structuredReply = aiInput.screenedChatReply(
            summary: " Resting heart rate is above its baseline. ",
            evidenceHighlights: [" HRV is below its baseline. "],
            limitation: "This comparison cannot establish a cause."
        )
        check(structuredReply == "Resting heart rate is above its baseline.\n\n• HRV is below its baseline.\n\nThis comparison cannot establish a cause.", "Structured chat renders trimmed and screened fields")
        check(aiInput.screenedChatReply(summary: "Resting heart rate differs from usual.", evidenceHighlights: [], limitation: " ") == nil, "Structured chat requires a limitation")
        check(aiInput.screenedChatReply(summary: "Resting heart rate differs from usual.", evidenceHighlights: ["Current value is 999 bpm."], limitation: "The cause is unknown.") == nil, "Structured chat screens highlights for numeric claims")
        check(disabledAIInput.screenedChatReply(summary: "Resting heart rate differs from usual.", evidenceHighlights: [], limitation: "HRV is also lower than usual.") == nil, "Structured chat screens limitations for opted-out evidence")
        print("All engine checks passed.")
    }
}
